const s1 = wb.getRange('Sheet1!A2:A14').getValues().map(r => String(r[0]));
const s2 = wb.getRange('Sheet2!A1:E11').getValues();
const items = {};
for (let c = 0; c < 5; c++) {
  items[String(s2[0][c])] = s2.slice(1).map(r => r[c]).filter(v => v !== null && v !== undefined && v !== '').map(String);
}
log(Object.entries(items).map(([k,v]) => k + ':' + v.length).join(', '));
const out = [];
const counts = [];
for (const e of s1) {
  const seg = e.split('+');
  const hdrs = Object.keys(items).filter(h => seg.includes(h));
  counts.push(hdrs.join('|') + ':' + hdrs.reduce((n,h)=>n+items[h].length,0));
  for (const h of hdrs) for (const it of items[h]) out.push([e + it]);
}
log(counts.join('\n'));
log('rows', out.length);
log('whitespace oddities', s1.filter(x=>x!==x.trim()).length, s2.flat().filter(x=>typeof x==='string' && x!==x.trim()).length);
log('style A41', wb.getRange('Sheet3!A41').getCell());
wb.getRange('Sheet3!A2:A' + (out.length + 1)).setValues(out);
wb.getRange('Sheet3!A1:A' + (out.length + 3))

